// Checkout conversion fix: ensure paidEvents increments on successful payment
const { logEvent } = require('./eventLogger');

module.exports = function fixCheckoutConversion(req, res, next) {
  const originalJson = res.json.bind(res);
  res.json = function (body) {
    if (res.statusCode === 200 && body && body.success) {
      logEvent('paidEvent', { timestamp: Date.now(), amount: body.amount || 0 });
    }
    return originalJson(body);
  };
  next();
};
